import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"物品署名","description":"玩家可以為物品署名，用來製作屬於自己的個人化物品。","frontmatter":{"title":"物品署名","description":"玩家可以為物品署名，用來製作屬於自己的個人化物品。"},"headers":[],"relativePath":"feature/signature/index.md","filePath":"feature/signature.md"}'),t={name:"feature/signature/index.md"};function o(u,l,n,s,d,c){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="物品署名" tabindex="-1">物品署名 <a class="header-anchor" href="#物品署名" aria-label="Permalink to &quot;物品署名&quot;">​</a></h1><h2 id="功能介紹" tabindex="-1">功能介紹 <a class="header-anchor" href="#功能介紹" aria-label="Permalink to &quot;功能介紹&quot;">​</a></h2><ul><li>署名後的物品，上面會有你的名字</li><li>只有署名玩家才能解除署名</li><li>只有署名玩家才能使用鐵砧改名、修復 <ul><li><font color="red"><b>非署名玩家使用鐵砧會無效，且經驗值及物品仍會消耗</b></font></li></ul></li><li>可以將你的工具之類的上署名，就能知道這是誰的了</li><li>地圖不能署名，請使用<a href="/apply/form_paint/">畫作同步系統</a></li></ul><h2 id="加上-解除署名" tabindex="-1">加上/解除署名 <a class="header-anchor" href="#加上-解除署名" aria-label="Permalink to &quot;加上/解除署名&quot;">​</a></h2><ul><li><code>/signature add</code><b>將物品加上署名</b><ul><li>手持物品(數量不限，一次拿一堆就是全部署名上去)</li></ul></li><li><code>/signature remove</code><b>將物品解除署名</b><ul><li>只有當事人能解除署名</li></ul></li></ul><h3 id="署名樣式" tabindex="-1">署名樣式 <a class="header-anchor" href="#署名樣式" aria-label="Permalink to &quot;署名樣式&quot;">​</a></h3><img src="https://i.imgur.com/OTNWhio.png" style="width:30%;"><h2 id="署名發行" tabindex="-1">署名發行 <a class="header-anchor" href="#署名發行" aria-label="Permalink to &quot;署名發行&quot;">​</a></h2><ul><li><code>/signature release</code><b>將物品署名發行</b><ul><li>手持由你署名的物品(數量不限，一次拿一堆就是全部發行)</li><li>建議使用方式 <ol><li>先將物品進行署名</li><li>將署名的物品以鐵砧改名</li><li>再使用此功能 能讓改名後的物品名稱變成正體字<br> (不然你拿鐵砧改會是斜體)</li></ol></li><li>可用在物品的驗證 <ul><li>只有你做的出來署名&amp;正體字的道具 別人做不出來<br> 用以確保這一定是你的</li><li>例如 : 自己做抽獎券/兌換券...<br><img src="https://i.imgur.com/rV29Gs2.png" style="width:30%;"></li></ul></li></ul></li></ul><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>方塊使用後(放置、合成等)署名會消失</li><li>署名是紀錄ID 所以如果你要改ID 請務必先解除署名 <ul><li>當你更改ID後若需要解除署名，請利用<a href="/discord/customer_service/">客服系統</a>請管理員協助處理</li></ul></li></ul>',11)])])}const b=i(t,[["render",o]]);export{m as __pageData,b as default};
